import{_ as e,o as a,c as n,a3 as d}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Agent 开发总览","description":"说明 Agent 开发模块的作用、学习目标、内容边界与推荐路径。","frontmatter":{"title":"Agent 开发总览","description":"说明 Agent 开发模块的作用、学习目标、内容边界与推荐路径。"},"headers":[],"relativePath":"py-agent/agent/index.md","filePath":"py-agent/agent/index.md","lastUpdated":1785380441000}'),r={name:"py-agent/agent/index.md"};function i(l,t,o,g,h,s){return a(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="agent-开发总览" tabindex="-1">Agent 开发总览 <a class="header-anchor" href="#agent-开发总览" aria-label="Permalink to &quot;Agent 开发总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本模块回答一个核心问题：怎样用 LangChain 构建边界清楚、能够调用工具并可被应用控制的单 Agent。它承接“基础与模型”中的 Python、模型调用和结构化输出知识，为后续 RAG、记忆、LangGraph 工作流、多 Agent 及生产工程建立共同运行模型。</p><h2 id="_1-模块作用" tabindex="-1">1. 模块作用 <a class="header-anchor" href="#_1-模块作用" aria-label="Permalink to &quot;1. 模块作用&quot;">​</a></h2><p>Agent 不是一个更长的 Prompt，而是“模型决策、工具执行、状态更新”组成的运行循环。本模块以 LangChain v1 为主要实现体系，同时把框架 API 放回 Agent 原理中解释：模型拥有哪些控制权，应用必须保留哪些确定性规则，状态、上下文和工具如何形成安全边界。</p><h2 id="_2-学习目标" tabindex="-1">2. 学习目标 <a class="header-anchor" href="#_2-学习目标" aria-label="Permalink to &quot;2. 学习目标&quot;">​</a></h2><p>完成本模块后，你应该能够：</p><ol><li>区分模型调用、固定 Workflow 与 Agent，并判断是否真的需要 Agent；</li><li>解释 Agent 执行循环，以及 AIMessage、ToolMessage 和工具调用之间的关系；</li><li>使用 Chat Models、Messages、Tools 和 <code>create_agent()</code> 构建单 Agent；</li><li>为工具定义 Schema、运行错误、授权和副作用边界，并理解 MCP 的集成位置；</li><li>区分 Agent State、Runtime Context、Store、模型上下文和业务数据；</li><li>使用 Middleware 实现动态 Prompt、模型与工具选择、错误处理和 Guardrails；</li><li>为 Agent 设计结构化结果、调用预算、停止条件和分层测试；</li><li>完成一个只读、受权限约束的工具型 Agent。</li></ol><h2 id="_3-学习路径" tabindex="-1">3. 学习路径 <a class="header-anchor" href="#_3-学习路径" aria-label="Permalink to &quot;3. 学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>解决的问题</th><th>学习结果</th></tr></thead><tbody><tr><td><a href="/py-agent/agent/agent-langchain/">Agent 与 LangChain</a></td><td>Agent 为什么存在、怎样循环</td><td>建立原理并运行最小 Agent</td></tr><tr><td><a href="/py-agent/agent/models-messages/">模型与消息</a></td><td>模型、消息和结果如何形成契约</td><td>能正确调用模型并处理消息对象</td></tr><tr><td><a href="/py-agent/agent/tools-mcp/">工具与 MCP</a></td><td>模型怎样连接应用能力</td><td>能设计工具并接入 MCP Server</td></tr><tr><td><a href="/py-agent/agent/agent-runtime/">LangChain Agent Runtime</a></td><td>Agent 怎样创建、保存状态和运行</td><td>掌握 <code>create_agent()</code> 与调用接口</td></tr><tr><td><a href="/py-agent/agent/context-middleware/">上下文与 Middleware</a></td><td>每一步看到什么、如何受控</td><td>能设计上下文与横切运行策略</td></tr><tr><td><a href="/py-agent/agent/design-practice/">设计与实践</a></td><td>如何选模式并形成完整应用</td><td>能实现和验收工具型 Agent</td></tr></tbody></table><p>建议按表中顺序学习。已经熟悉 LangChain Core 的读者仍应先阅读第一组，因为后文对 State、Context 和 Middleware 的解释都建立在执行循环上。</p><h2 id="_4-内容边界" tabindex="-1">4. 内容边界 <a class="header-anchor" href="#_4-内容边界" aria-label="Permalink to &quot;4. 内容边界&quot;">​</a></h2><p>本模块聚焦 LangChain 单 Agent 的开发基础，不展开以下主题：</p><ul><li>文档切分、Embedding、检索和长期记忆，放在“知识与记忆”；</li><li>LangGraph 状态图、持久化工作流和多 Agent 协作，放在“工作流与多 Agent”；</li><li>FastAPI 服务、业务数据库、Redis 和后台任务，放在“Agent 应用工程”；</li><li>系统化评测、安全治理、可观测和部署，放在“质量与生产工程”；</li><li>复杂企业架构与综合项目，放在“架构与实战”。</li></ul><p>文中仍会讲清与这些主题相接的边界，但不会提前把多个模块混成一套大而散的教程。</p><h2 id="_5-前置知识" tabindex="-1">5. 前置知识 <a class="header-anchor" href="#_5-前置知识" aria-label="Permalink to &quot;5. 前置知识&quot;">​</a></h2><p>开始前应掌握 Python 函数、类型标注、异常、异步基础、HTTP 客户端，以及聊天模型的消息和结构化输出概念。相关内容可以在“基础与模型”模块复习。</p><h2 id="_6-学习方法" tabindex="-1">6. 学习方法 <a class="header-anchor" href="#_6-学习方法" aria-label="Permalink to &quot;6. 学习方法&quot;">​</a></h2><p>阅读每篇文章时，优先回答三个问题：谁决定下一步、数据存在哪里、失败由谁处理。代码用于观察和验证这些机制；示例能够运行，不代表其权限、持久化和错误策略已经适合生产。</p>',19)])])}const _=e(r,[["render",i]]);export{c as __pageData,_ as default};
